  .recommendation p {{ margin: 0; }}
  footer {{
    text-align: center;
    color: var(--color-muted);
    font-size: 0.85rem;
    padding: 20px;
  }}
  @media (max-width: 640px) {{
    .kpi-grid {{ grid-template-columns: 1fr 1fr; }}
    header h1 {{ font-size: 1.3rem; }}
  }}
</style>
</head>
<body>
<header>
  <h1>EV Charging Network Performance & Grid Optimization Analytics Report</h1>
  <p>Data-driven insights for infrastructure managers and grid planners</p>
</header>
<div class="container">
